-- V Coin admin/master financial workflow patch. Run once in Supabase SQL Editor.
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
do $$ begin execute 'alter extension pgcrypto set schema extensions'; exception when others then null; end $$;
create or replace function public.gen_random_bytes(p_len integer) returns bytea language sql volatile security definer set search_path=extensions as $$ select extensions.gen_random_bytes(p_len) $$;
revoke all on function public.gen_random_bytes(integer) from public; grant execute on function public.gen_random_bytes(integer) to authenticated, service_role;
insert into public.permissions(code,label) values ('CREATE_USER','Create users'),('VIEW_USERS','View users'),('EDIT_USER','Edit users'),('DEACTIVATE_USER','Deactivate user'),('VCOIN_REQUESTS','V Coin requests'),('CRYPTO_REQUESTS','Crypto requests'),('BANK_TRANSFER_REQUESTS','Bank transfer requests'),('APPROVE_REQUESTS','Approve requests'),('VIEW_COMMISSION','View commission'),('VIEW_TRANSACTIONS','View transactions'),('VIEW_REPORTS','View reports') on conflict(code) do update set label=excluded.label;
create or replace function public.record_charge_commission(p_user uuid,p_master uuid,p_type text,p_reference text,p_transaction_amount numeric,p_charge numeric) returns void language plpgsql security definer set search_path=public as $$declare mp numeric:=0;mc numeric:=0;cc numeric:=0;begin if coalesce(p_charge,0)<=0 then return;end if;if exists(select 1 from commissions where transaction_reference=p_reference and transaction_type=p_type) then return;end if;if p_master is not null then select coalesce(master_percentage,0) into mp from commission_rules where master_id=p_master and is_active=true;mp:=coalesce(mp,0);end if;mc:=round(p_charge*mp/100,8);cc:=round(p_charge-mc,8);insert into commissions(master_id,user_id,transaction_type,transaction_reference,transaction_amount,total_charge,master_commission,company_commission) values(p_master,p_user,p_type,p_reference,p_transaction_amount,p_charge,mc,cc);end$$;
create or replace function public.process_request(p_kind text,p_request_id text,p_action text,p_note text) returns jsonb language plpgsql security definer set search_path=public as $$declare me profiles%rowtype;uid uuid;mid uuid;wid uuid;amt numeric;business_charge numeric:=0;network_chg numeric:=0;rid text;before numeric;locked_before numeric;afterb numeric;current_status request_status;k text:=upper(p_kind);a text:=upper(p_action);begin select * into me from profiles where id=auth.uid();if me.role not in ('super_admin','admin','master') or me.status<>'active' then raise exception 'Not authorized';end if;if me.role='master' and not has_permission('APPROVE_REQUESTS') then raise exception 'APPROVE_REQUESTS permission required';end if;if a not in ('APPROVED','COMPLETE','REJECTED','CANCELLED','PAYMENT_PENDING','PAYMENT_SUBMITTED','PAYMENT_CONFIRMED') then raise exception 'Invalid action';end if;
if k='TOPUP' then select user_id,master_id,requested_vcoin,topup_charge,request_id,status into uid,mid,amt,business_charge,rid,current_status from topup_requests where id=p_request_id::uuid for update;if uid is null then raise exception 'Request not found';end if;if me.role='master' and mid is distinct from me.id then raise exception 'Not your assigned request';end if;if current_status in ('completed','rejected','cancelled') then raise exception 'Request already finalized';end if;if a='COMPLETE' then select id,vcoin_balance into wid,before from wallets where user_id=uid for update;afterb:=before+amt;update wallets set vcoin_balance=afterb,updated_at=now() where id=wid;insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(rid||'-C',wid,'TOPUP','CREDIT',amt,before,afterb,rid,'Top-up completed','PROC-'||rid);update topup_requests set status='completed',updated_at=now() where id=p_request_id::uuid;if business_charge>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(uid,mid,'VCOIN_TOPUP',rid,business_charge);perform record_charge_commission(uid,mid,'VCOIN_TOPUP',rid,amt,business_charge);end if;insert into notifications(user_id,title,message,type,reference_id) values(uid,'Top-up completed',amt||' VC credited','TOPUP',rid);else update topup_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;end if;
elsif k='CRYPTO' then select user_id,master_id,vcoin_amount,conversion_charge,network_charge,request_id,status into uid,mid,amt,business_charge,network_chg,rid,current_status from crypto_conversion_requests where id=p_request_id::uuid for update;if uid is null then raise exception 'Request not found';end if;if me.role='master' and mid is distinct from me.id then raise exception 'Not your assigned request';end if;if current_status in ('completed','rejected','cancelled') then raise exception 'Request already finalized';end if;select id,vcoin_balance,locked_balance into wid,before,locked_before from wallets where user_id=uid for update;if a='COMPLETE' then if locked_before<amt then raise exception 'Locked balance mismatch';end if;afterb:=before-amt;update wallets set vcoin_balance=afterb,locked_balance=locked_balance-amt,updated_at=now() where id=wid;insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(rid||'-D',wid,'CRYPTO_CONVERSION','DEBIT',amt,before,afterb,rid,'Crypto conversion completed','PROC-'||rid);update crypto_conversion_requests set status='completed',updated_at=now() where id=p_request_id::uuid;if business_charge>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(uid,mid,'CRYPTO_CONVERSION',rid,business_charge);perform record_charge_commission(uid,mid,'CRYPTO_CONVERSION',rid,amt,business_charge);end if;if network_chg>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(uid,mid,'CRYPTO_NETWORK',rid,network_chg);end if;insert into crypto_transactions(crypto_request_id,crypto_asset_id,wallet_address,crypto_amount,transaction_hash,network,processed_by,processed_at) select c.id,c.crypto_asset_id,c.destination_wallet,c.final_crypto_amount,nullif(p_note,''),a2.network,auth.uid(),now() from crypto_conversion_requests c join crypto_assets a2 on a2.id=c.crypto_asset_id where c.id=p_request_id::uuid;elsif a in ('REJECTED','CANCELLED') then update wallets set locked_balance=greatest(locked_balance-amt,0),updated_at=now() where id=wid;update crypto_conversion_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;else update crypto_conversion_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;end if;
elsif k='BANK' then select user_id,master_id,vcoin_amount,transfer_charge,request_id,status into uid,mid,amt,business_charge,rid,current_status from bank_transfer_requests where id=p_request_id::uuid for update;if uid is null then raise exception 'Request not found';end if;if me.role='master' and mid is distinct from me.id then raise exception 'Not your assigned request';end if;if current_status in ('completed','rejected','cancelled') then raise exception 'Request already finalized';end if;select id,vcoin_balance,locked_balance into wid,before,locked_before from wallets where user_id=uid for update;if a='COMPLETE' then if locked_before<amt then raise exception 'Locked balance mismatch';end if;afterb:=before-amt;update wallets set vcoin_balance=afterb,locked_balance=locked_balance-amt,updated_at=now() where id=wid;insert into wallet_transactions(transaction_id,wallet_id,transaction_type,direction,amount,balance_before,balance_after,reference_id,description,idempotency_key) values(rid||'-D',wid,'BANK_TRANSFER','DEBIT',amt,before,afterb,rid,'Bank transfer completed','PROC-'||rid);update bank_transfer_requests set status='completed',updated_at=now() where id=p_request_id::uuid;if business_charge>0 then insert into charge_history(user_id,master_id,transaction_type,reference_id,amount) values(uid,mid,'BANK_TRANSFER',rid,business_charge);perform record_charge_commission(uid,mid,'BANK_TRANSFER',rid,amt,business_charge);end if;insert into bank_transfer_transactions(bank_request_id,bank_reference_number,amount,processed_by,processed_at,remarks) select id,nullif(p_note,''),final_bank_amount,auth.uid(),now(),p_note from bank_transfer_requests where id=p_request_id::uuid;elsif a in ('REJECTED','CANCELLED') then update wallets set locked_balance=greatest(locked_balance-amt,0),updated_at=now() where id=wid;update bank_transfer_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;else update bank_transfer_requests set status=lower(a)::request_status,updated_at=now() where id=p_request_id::uuid;end if;else raise exception 'Unknown request kind';end if;insert into audit_logs(user_id,action,module,reference_id,new_data) values(auth.uid(),a,k,p_request_id,jsonb_build_object('note',coalesce(p_note,''),'request_id',rid));return jsonb_build_object('success',true,'kind',k,'action',a,'request_id',rid);end$$;
revoke all on function public.process_request(text,text,text,text) from public;grant execute on function public.process_request(text,text,text,text) to authenticated;